package com.nova.vpn.android.wear

import org.junit.Assert.*
import org.junit.Test

class WearProfileProtocolTest {
    private val id = "01a08be1-4342-71a3-8cf2-00ae603b2fc4"
    private val config = """{ "outbounds": [{"type":"vless","tag":"тест \"узел\"","server":"example.test"}] }"""

    @Test fun utf8AndEscapedConfigurationSurvivesTransfer() {
        val request = WearProfileProtocol.decode(WearProfileProtocol.encode(id, config))!!
        assertEquals(id, request.id)
        assertEquals(config, request.config)
    }
    @Test fun acknowledgementMustMatchRequestAndKnownResult() {
        assertEquals("stored", WearProfileProtocol.result(WearProfileProtocol.reply(id, "stored"), id))
        assertEquals("storage_error", WearProfileProtocol.result(WearProfileProtocol.reply(id, "storage_error"), id))
        assertNull(WearProfileProtocol.result(WearProfileProtocol.reply(id, "stored"), "00000000-0000-0000-0000-000000000000"))
        assertNull(WearProfileProtocol.result("""{"requestId":"$id","result":"sent"}""".toByteArray(), id))
        assertNull(WearProfileProtocol.result(ByteArray(1025), id))
    }
    @Test fun invalidAndOversizedMessagesCannotOverwriteProfile() {
        assertNull(WearProfileProtocol.decode(ByteArray(WearProfileProtocol.MAX_BYTES + 1)))
        assertNull(WearProfileProtocol.decode("""{"requestId":"invalid","config":"{}"}""".toByteArray()))
        assertFalse(WearProfileProtocol.validConfig("""{"outbounds":[]}"""))
        assertFalse(WearProfileProtocol.validConfig("""{"outbounds":"not-an-array"}"""))
        assertFalse(WearProfileProtocol.validConfig("not json"))
        assertNull(WearProfileProtocol.decode("""{"requestId":"$id","config":"{}"}""".toByteArray()))
    }
    @Test fun limitIncludesJsonEnvelopeAndEscaping() {
        val large = """{"outbounds":[{"type":"vless","tag":"жжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжжж